mapper.select:
SELECT *
FROM match_event_info
WHERE standard_match_id = #{standardMatchId}
  AND data_source_code = #{dataSourceCode}
  AND third_match_source_id = #{thirdMatchSourceId}
  AND event_time  < #{eventTime}
ORDER BY event_time desc
    LIMIT #{size}

SELECT id
FROM match_event_info
WHERE data_source_code = #{dataSourceCode}
  AND create_time  < #{dayDateTime}

mapper.delete:
DELETE FROM  ${tableName}
WHERE modify_time  < #{dayDateTime}
    ORDER BY event_time
LIMIT #{size}

mapper.update:
UPDATE ${tableName}
SET standard_match_id = #{standardMatchId}
,modify_time = #{modifyTime}
WHERE third_match_id = #{thirdMatchId}
AND third_match_source_id = #{thirdMatchSourceId}
AND COALESCE(standard_match_id,0) = 0

UPDATE ${tableName}
SET standard_match_id = #{standardMatchId}
    ,send_data = 'Y'
    ,link_id = #{linkId}
    ,modify_time = #{modifyTime}
WHERE third_match_id = #{thirdMatchId}
AND third_match_source_id = #{thirdMatchSourceId}
AND send_data = 'N'
